CREATE PROCEDURE ORDER_AUDIT.P_RECEIVE_EVENT WITH EXECUTE AS OWNER AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @dialog uniqueidentifier, @body varbinary(max), @type sysname;
 BEGIN TRANSACTION;
 WAITFOR (RECEIVE TOP (1) @dialog = conversation_handle, @body = message_body, @type = message_type_name FROM ORDER_AUDIT.EVENT_INBOX), TIMEOUT 5000;
 IF @dialog IS NOT NULL
 BEGIN
  IF @type = N'ITEM_EVENT'
  BEGIN
   DECLARE @payload xml = CAST(@body AS xml);
   INSERT INTO ORDER_AUDIT.AUDIT_LOG (ID, AMOUNT) VALUES (@payload.value('(/item/ID)[1]', 'int'), @payload.value('(/item/AMOUNT)[1]', 'int'));
  END;
  END CONVERSATION @dialog;
 END;
 COMMIT;
END;

